import "./roll-text.css";

/**
 * RollText — on hover of the nearest link/button, each letter rolls up out of sight and its copy
 * rolls in from below, one letter after another (CSS only: an ancestor with .roll-host triggers it).
 * The text is in the page once, whole: the rolling letters and their copies are drawn by CSS from
 * data-c (roll-text.css), so search engines and screen readers read the word, not its letters twice.
 */
export function RollText({ children }: { children: string }) {
  return (
    <>
      <span className="visually-hidden">{children}</span>
      <span className="roll" aria-hidden="true">
        {[...children].map((char, i) => (
          <span className="roll__c" key={i} data-c={char} style={{ "--i": i } as React.CSSProperties} />
        ))}
      </span>
    </>
  );
}

/* RollText: on hover each letter rolls up out of sight and its copy rolls in from below. The letter and
   its copy are generated content (data-c): the page's text holds the word once. */

.roll { display: inline-flex; overflow: hidden; }
.roll__c { position: relative; display: flex; flex-direction: column; }
.roll__c::before,
.roll__c::after {
  content: attr(data-c);
  display: block;
  white-space: pre;
  transition: transform 0.4s cubic-bezier(0.33, 1, 0.68, 1) calc(var(--i) * 20ms);
}
.roll__c::after { position: absolute; top: 0; left: 0; right: 0; transform: translateY(100%); }
@media (prefers-reduced-motion: reduce) {
  .roll__c::before,
  .roll__c::after { transition: none; }
}
/* the trigger: any ancestor with .roll-host (the site's nav links bring their own rule, header.css) */
.roll-host:hover .roll__c::before,
.roll-host:focus-visible .roll__c::before { transform: translateY(-100%); }
.roll-host:hover .roll__c::after,
.roll-host:focus-visible .roll__c::after { transform: translateY(0); }
